import React, { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { getInspectionDetail, submitInspection } from '../../services/technicianService';
import toast from 'react-hot-toast';

const InspectCar = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [car, setCar] = useState(null);
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [form, setForm] = useState({
    engineCondition: 'good',
    transmissionCondition: 'good',
    chassisCondition: 'good',
    electricalCondition: 'good',
    exteriorDetail: '',
    interiorDetail: '',
    engineDetail: '',
    transmissionDetail: '',
    chassisDetail: '',
    electricalDetail: '',
    overallRating: 3,
    technicianNotes: '',
  });

  useEffect(() => {
    const fetch = async () => {
      try {
        const data = await getInspectionDetail(id);
        setCar(data);
        // Nếu đã có dữ liệu technical cũ thì load lên form
        if (data.technical && data.technical.inspectedBy) {
          setForm({
            engineCondition: data.technical.engineCondition || 'good',
            transmissionCondition: data.technical.transmissionCondition || 'good',
            chassisCondition: data.technical.chassisCondition || 'good',
            electricalCondition: data.technical.electricalCondition || 'good',
            exteriorDetail: data.technical.exteriorDetail || '',
            interiorDetail: data.technical.interiorDetail || '',
            engineDetail: data.technical.engineDetail || '',
            transmissionDetail: data.technical.transmissionDetail || '',
            chassisDetail: data.technical.chassisDetail || '',
            electricalDetail: data.technical.electricalDetail || '',
            overallRating: data.technical.overallRating || 3,
            technicianNotes: data.technical.technicianNotes || '',
          });
        }
      } catch (err) {
        toast.error('Không thể tải thông tin xe');
        navigate('/technician/dashboard');
      } finally {
        setLoading(false);
      }
    };
    fetch();
  }, [id, navigate]);

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setSubmitting(true);
    try {
      await submitInspection(id, form);
      toast.success('Đã lưu kết quả kiểm tra');
      navigate('/technician/dashboard');
    } catch (err) {
      toast.error(err.response?.data?.message || 'Lưu thất bại');
    } finally {
      setSubmitting(false);
    }
  };

  if (loading) return <div className="text-center p-8">Đang tải thông tin xe...</div>;
  if (!car) return null;

  return (
    <div className="max-w-4xl mx-auto p-6">
      <h2 className="text-2xl font-bold mb-2">Kiểm tra kỹ thuật xe</h2>
      <div className="bg-gray-50 p-4 rounded mb-6">
        <p><strong>{car.brand} {car.model}</strong> - {car.year}</p>
        <p>Số km: {car.mileage.toLocaleString()} km</p>
        <p>Khách hàng: {car.customer.name}</p>
      </div>

      <form onSubmit={handleSubmit} className="space-y-6">
        {/* Đánh giá từng bộ phận */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div>
            <label className="block font-medium">Tình trạng động cơ</label>
            <select name="engineCondition" value={form.engineCondition} onChange={handleChange} className="w-full border rounded p-2">
              <option value="good">Tốt</option>
              <option value="fair">Trung bình</option>
              <option value="poor">Kém</option>
            </select>
          </div>
          <div>
            <label className="block font-medium">Tình trạng hộp số</label>
            <select name="transmissionCondition" value={form.transmissionCondition} onChange={handleChange} className="w-full border rounded p-2">
              <option value="good">Tốt</option>
              <option value="fair">Trung bình</option>
              <option value="poor">Kém</option>
            </select>
          </div>
          <div>
            <label className="block font-medium">Tình trạng khung gầm</label>
            <select name="chassisCondition" value={form.chassisCondition} onChange={handleChange} className="w-full border rounded p-2">
              <option value="good">Tốt</option>
              <option value="fair">Trung bình</option>
              <option value="poor">Kém</option>
            </select>
          </div>
          <div>
            <label className="block font-medium">Hệ thống điện</label>
            <select name="electricalCondition" value={form.electricalCondition} onChange={handleChange} className="w-full border rounded p-2">
              <option value="good">Tốt</option>
              <option value="fair">Trung bình</option>
              <option value="poor">Kém</option>
            </select>
          </div>
        </div>

        {/* Mô tả chi tiết */}
        <div>
          <label className="block font-medium">Chi tiết ngoại thất</label>
          <textarea name="exteriorDetail" value={form.exteriorDetail} onChange={handleChange} rows="2" className="w-full border rounded p-2" placeholder="Mô tả trầy xước, móp, thay thế phụ tùng..."></textarea>
        </div>
        <div>
          <label className="block font-medium">Chi tiết nội thất</label>
          <textarea name="interiorDetail" value={form.interiorDetail} onChange={handleChange} rows="2" className="w-full border rounded p-2" placeholder="Tình trạng ghế, bảng điều khiển, điều hòa..."></textarea>
        </div>
        <div>
          <label className="block font-medium">Chi tiết động cơ</label>
          <textarea name="engineDetail" value={form.engineDetail} onChange={handleChange} rows="2" className="w-full border rounded p-2" placeholder="Tiếng kêu lạ, khói, rò rỉ nhớt..."></textarea>
        </div>
        <div>
          <label className="block font-medium">Chi tiết hộp số</label>
          <textarea name="transmissionDetail" value={form.transmissionDetail} onChange={handleChange} rows="2" className="w-full border rounded p-2"></textarea>
        </div>
        <div>
          <label className="block font-medium">Chi tiết khung gầm</label>
          <textarea name="chassisDetail" value={form.chassisDetail} onChange={handleChange} rows="2" className="w-full border rounded p-2"></textarea>
        </div>
        <div>
          <label className="block font-medium">Chi tiết hệ thống điện</label>
          <textarea name="electricalDetail" value={form.electricalDetail} onChange={handleChange} rows="2" className="w-full border rounded p-2"></textarea>
        </div>

        {/* Đánh giá tổng quan */}
        <div>
          <label className="block font-medium">Đánh giá tổng quan (1-5 sao)</label>
          <input type="number" name="overallRating" min="1" max="5" value={form.overallRating} onChange={handleChange} className="w-32 border rounded p-2" />
        </div>

        <div>
          <label className="block font-medium">Ghi chú kỹ thuật viên</label>
          <textarea name="technicianNotes" value={form.technicianNotes} onChange={handleChange} rows="3" className="w-full border rounded p-2"></textarea>
        </div>

        <div className="flex space-x-3">
          <button type="submit" disabled={submitting} className="bg-green-600 text-white px-6 py-2 rounded hover:bg-green-700 disabled:opacity-50">
            {submitting ? 'Đang lưu...' : 'Hoàn tất kiểm tra'}
          </button>
          <button type="button" onClick={() => navigate('/technician/dashboard')} className="bg-gray-300 px-6 py-2 rounded">Hủy</button>
        </div>
      </form>
    </div>
  );
};

export default InspectCar;
